const items = $input.all().map(i => i.json);

// Filter and enrich valid seller leads
const qualifiedLeads = [];

for (const item of items) {
  const seller = item.seller || {};
  const hasEmail = Boolean(seller.email && seller.email.includes('@'));
  const score = seller.feedbackScore || 0;
  const rating = seller.positiveFeedbackPercent || 0;

  // Determine merchant trust tier
  let tier = 'Standard Merchant';
  if (score >= 5000 && rating >= 99) {
    tier = '🌟 VIP Enterprise Merchant';
  } else if (score >= 1000 && rating >= 98) {
    tier = '⭐ High-Volume Verified Seller';
  }

  qualifiedLeads.push({
    json: {
      item_id: item.item_id,
      listing_url: item.url,
      company_name: seller.companyName || 'Independent Merchant',
      seller_name: seller.seller || 'N/A',
      direct_email: seller.email || 'N/A',
      direct_phone: seller.phone || 'N/A',
      physical_address: seller.address || 'N/A',
      feedback_score: score,
      positive_feedback_rate: rating,
      store_url: seller.storeUrl || '',
      merchant_tier: tier,
      has_direct_email: hasEmail,
      cold_email_subject: `Direct Partnership Inquiry: ${seller.companyName || seller.seller || 'Store'}`,
      cold_email_icebreaker: `Hi ${seller.seller || 'team'}, I noticed your high-volume store (${score} verified reviews, ${rating}% positive rating) on eBay.`
    }
  });
}

return qualifiedLeads;
